CREATE TABLE IF NOT EXISTS kioku (id TEXT PRIMARY KEY, payload TEXT NOT NULL CHECK(json_valid(payload)), published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)));
INSERT INTO kioku (id,payload,published) VALUES ('sayaka-venusta-dissonanza','{"id": "sayaka-venusta-dissonanza", "character_ko": "미키 사야카", "character_ja": "美樹さやか", "name_ja": "ヴェヌスタ・ディソナンツァ", "rarity": 5, "role": "어태커", "element": "무속성", "limited": true, "stats": {"HP": 9526, "공격력": 4575, "방어력": 3283, "스피드": 103}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/sayaka-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지. 공식 게시물 URL과 게시일은 확인 대기.", "verification": "초기 전사 · 번역 검토 대기", "skills": [{"kind": "일반 공격", "name_ja": "通常攻撃", "cost": null, "break": 10, "ja": "敵単体に100%の無属性ダメージを与える。\n自身の受けるダメージ-10%(1ターン)", "ko": "적 하나에게 100%의 무속성 피해를 준다.\n자신이 받는 피해 -10%(1턴)."}, {"kind": "필살기", "name_ja": "ヴェヌスタ・ディソナンツァ", "cost": "MP 150", "break": 25, "ja": "敵全体に230%の無属性ダメージを与え、さらに10回ダメージを与える(1回ごとにランダムな敵単体に10%の無属性ダメージを与える)。\n自身の戦闘スキルで与えるダメージ+30%(2ターン)、HPを発動者の攻撃力30%回復する", "ko": "적 전체에게 230%의 무속성 피해를 주고, 추가로 10회 피해를 준다(매회 무작위 적 하나에게 10%의 무속성 피해).\n자신의 전투 스킬로 주는 피해 +30%(2턴). 발동자 공격력의 30%만큼 HP를 회복한다."}], "pending": ["전투 스킬과 추격·트랜스 변형", "어빌리티와 무속성 필드", "서포트 어빌리티", "전용 EX 결정 어빌리티", "한계돌파 1~5단계"]}',1);
